const echarts = require('echarts');
const fs = require('fs');

// Load source data
const sourceData = JSON.parse(fs.readFileSync('/app/benchmark/source_data.json', 'utf8'));
const airports = sourceData.airports.data;

// Region colors - categorical palette
const regionColors = {
  'North America': '#4e79a7',
  'Europe': '#f28e2b',
  'Asia-Pacific': '#e15759',
  'Middle East': '#76b7b2',
  'Latin America': '#59a14f',
  'Africa': '#edc948'
};

const seriesMap = {};
airports.forEach(a => {
  if (!seriesMap[a.region]) {
    seriesMap[a.region] = [];
  }
  seriesMap[a.region].push({
    name: a.airport,
    value: [a.throughput_million, a.on_time_rate, a.routes, a.region],
    // For label
    label: a.airport
  });
});

const series = Object.entries(seriesMap).map(([region, data]) => ({
  name: region,
  type: 'scatter',
  data: data.map(d => ({
    value: [d.value[0], d.value[1], d.value[2]],
    name: d.name
  })),
  symbolSize: function(data) {
    // Scale routes (95-370) to bubble area (8-40)
    const routes = data[2];
    return Math.sqrt(routes / 95) * 10;
  },
  itemStyle: {
    color: regionColors[region],
    opacity: 0.75
  },
  label: {
    show: false
  }
}));

// Now add annotation labels for the 3 outliers
const annotationData = airports.filter(a =>
  a.airport === 'Atlanta (ATL)' ||
  a.airport === 'Dubai (DXB)' ||
  a.airport === 'Tokyo Haneda (HND)'
).map(a => ({
  name: a.airport,
  value: [a.throughput_million, a.on_time_rate, a.routes],
  label: {
    show: true,
    formatter: a.airport.split('(')[0].trim(),
    fontSize: 11,
    fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    color: '#111'
  }
}));

// Add annotation series
series.push({
  name: 'Annotations',
  type: 'scatter',
  data: annotationData,
  symbolSize: function(data) {
    const routes = data[2];
    return Math.sqrt(routes / 95) * 10;
  },
  itemStyle: {
    color: 'transparent',
    borderColor: '#111',
    borderWidth: 1.5
  },
  label: {
    show: true,
    position: ['-30', '-20'],
    fontSize: 11,
    fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    color: '#111'
  },
  z: 100
});

// Compute axis ranges
const throughputs = airports.map(a => a.throughput_million);
const onTimeRates = airports.map(a => a.on_time_rate);
const minTP = Math.min(...throughputs);
const maxTP = Math.max(...throughputs);
const minOT = Math.min(...onTimeRates);
const maxOT = Math.max(...onTimeRates);

const option = {
  backgroundColor: '#fffff8',
  textStyle: {
    fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
    color: '#111'
  },
  grid: {
    show: false,
    left: 70,
    right: 60,
    top: 80,
    bottom: 50
  },
  legend: {
    show: true,
    orient: 'horizontal',
    bottom: 10,
    itemGap: 20,
    textStyle: {
      fontSize: 11,
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif',
      color: '#666'
    }
  },
  tooltip: {
    backgroundColor: 'rgba(255,255,248,0.95)',
    borderWidth: 0,
    textStyle: {
      fontSize: 12,
      color: '#333',
      fontFamily: 'system-ui, sans-serif'
    },
    extraCssText: 'box-shadow: none;',
    formatter: function(params) {
      const d = params.data;
      const name = d.name || (params.data && params.data.name) || params.seriesName;
      return `<b>${name}</b><br/>Throughput: ${d.value[0]}M passengers<br/>On-time: ${d.value[1]}%<br/>Routes: ${d.value[2]}`;
    }
  },
  xAxis: {
    type: 'value',
    name: 'Annual Passenger Throughput (millions)',
    nameLocation: 'center',
    nameGap: 40,
    nameTextStyle: {
      fontSize: 12,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif'
    },
    min: Math.floor(minTP - 5),
    max: Math.ceil(maxTP + 5),
    axisLine: { show: true, lineStyle: { color: '#ccc', width: 0.5 } },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, sans-serif'
    },
    splitLine: { show: false }
  },
  yAxis: {
    type: 'value',
    name: 'On-Time Performance (%)',
    nameLocation: 'center',
    nameGap: 50,
    nameTextStyle: {
      fontSize: 12,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif'
    },
    min: Math.floor(minOT - 2),
    max: Math.ceil(maxOT + 2),
    axisLine: { show: true, lineStyle: { color: '#ccc', width: 0.5 } },
    axisTick: { show: false },
    axisLabel: {
      color: '#999',
      fontSize: 11,
      fontFamily: 'system-ui, sans-serif'
    },
    splitLine: { show: false }
  },
  series: series,
  title: {
    text: 'Airport Performance: Throughput vs. On-Time Performance',
    subtext: 'Bubble size represents number of routes; color indicates region',
    left: 'left',
    textStyle: {
      fontSize: 16,
      fontWeight: 'normal',
      color: '#111',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif'
    },
    subtextStyle: {
      fontSize: 12,
      color: '#666',
      fontFamily: '"ET Book", "Palatino Linotype", Palatino, Georgia, serif'
    }
  }
};

// Create chart and save
const chart = echarts.init(null, 'tufte');
chart.setOption(option);

// Render to PNG
const buffer = chart.getDom().toBuffer('image/png');
fs.writeFileSync('/app/output/result.png', buffer);

chart.dispose();
console.log('Chart saved to /app/output/result.png');

