const puppeteer = require('puppeteer');
const echarts = require('echarts');
const fs = require('fs');

async function generateChart() {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  const htmlContent = `<!DOCTYPE html>
<html>
<head>
  <meta charset=\"utf-8\">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { background-color: #fffff8; }
    #chart { width: 900px; height: 600px; }
  </style>
</head>
<body>
  <div id=\"chart\"></div>
  <script src=\"node_modules/echarts/dist/echarts.min.js\"></script>
  <script>
    const airports = ${JSON.stringify(require('/app/benchmark/source_data.json').airports.data)};

    const regionColors = {
      'North America': '#4e79a7',
      'Europe': '#f28e2b',
      'Asia-Pacific': '#e15759',
      'Middle East': '#76b7b2',
      'Latin America': '#59a14f',
      'Africa': '#edc948'
    };

    // Create series by region
    const series = [];
    const regions = ['North America', 'Europe', 'Asia-Pacific', 'Middle East', 'Latin America', 'Africa'];

    regions.forEach(region => {
      const regionAirports = airports.filter(a => a.region === region);
      const data = regionAirports.map(a => ({
        name: a.airport,
        value: [a.throughput_million, a.on_time_rate, a.routes]
      }));

      series.push({
        name: region,
        type: 'scatter',
        data: data,
        symbolSize: function(data) {
          return Math.sqrt(data[2] / 95) * 14;
        },
        itemStyle: { color: regionColors[region], opacity: 0.8 },
        label: { show: false }
      });
    });

    // Compute axis ranges
    const throughputs = airports.map(a => a.throughput_million);
    const onTimeRates = airports.map(a => a.on_time_rate);

    const option = {
      backgroundColor: '#fffff8',
      textStyle: {
        fontFamily: 'Georgia, serif',
        color: '#111'
      },
      grid: { show: false, left: 80, right: 60, top: 90, bottom: 70 },
      legend: {
        show: true,
        orient: 'horizontal',
        bottom: 15,
        itemGap: 16,
        itemWidth: 14,
        textStyle: { fontSize: 11, fontFamily: 'Georgia, serif', color: '#666' }
      },
      tooltip: {
        backgroundColor: 'rgba(255,255,248,0.95)',
        borderWidth: 0,
        textStyle: { fontSize: 12, color: '#333', fontFamily: 'sans-serif' },
        extraCssText: 'box-shadow: none;'
      },
      xAxis: {
        type: 'value',
        name: 'Annual Passenger Throughput (millions)',
        nameLocation: 'center',
        nameGap: 45,
        nameTextStyle: { fontSize: 12, color: '#666', fontFamily: 'Georgia, serif' },
        min: Math.floor(Math.min(...throughputs) - 5),
        max: Math.ceil(Math.max(...throughputs) + 5),
        axisLine: { show: true, lineStyle: { color: '#ccc', width: 0.5 } },
        axisTick: { show: false },
        axisLabel: { color: '#999', fontSize: 11 },
        splitLine: { show: false }
      },
      yAxis: {
        type: 'value',
        name: 'On-Time Performance (%)',
        nameLocation: 'center',
        nameGap: 55,
        nameTextStyle: { fontSize: 12, color: '#666', fontFamily: 'Georgia, serif' },
        min: Math.floor(Math.min(...onTimeRates) - 2),
        max: Math.ceil(Math.max(...onTimeRates) + 2),
        axisLine: { show: true, lineStyle: { color: '#ccc', width: 0.5 } },
        axisTick: { show: false },
        axisLabel: { color: '#999', fontSize: 11 },
        splitLine: { show: false }
      },
      series: series,
      title: {
        text: 'Airport Performance: Throughput vs. On-Time Performance',
        subtext: 'Bubble size = number of routes | Color = geographic region',
        left: 'left',
        textStyle: { fontSize: 16, fontWeight: 'normal', color: '#111', fontFamily: 'Georgia, serif' },
        subtextStyle: { fontSize: 12, color: '#666', fontFamily: 'Georgia, serif' }
      }
    };

    const chart = echarts.init(document.getElementById('chart'));
    chart.setOption(option);
  </script>
</body>
</html>`;

  await page.setContent(htmlContent);
  await page.waitForSelector('#chart canvas', { timeout: 10000 });

  // Wait a bit for chart to render
  await new Promise(r => setTimeout(r, 1000));

  const screenshot = await page.screenshot({ type: 'png' });
  fs.writeFileSync('/app/output/result.png', screenshot);

  await browser.close();
  console.log('Chart saved to /app/output/result.png');
}

generateChart().catch(err => {
  console.error(err);
  process.exit(1);
});

